SELECT CAST(COUNT(DISTINCT CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM p.dob) = 1970 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND d.diagnosis_code IN ('250.0', '250.1') AND e.event_type_code = 'I' AND f.infusion_rate_unit = 'pp' AND f.infusion_rate_adjustment_amount IS NULL AND g.order_type = 'I' AND h.starttime BETWEEN 0 AND 72 THEN f.infusion_rate_adjustment END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM p.dob) = 1970 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND d.diagnosis_code IN ('250.0', '250.1') AND e.event_type_code = 'I' AND f.infusion_rate_unit = 'pp' AND f.infusion_rate_adjustment_amount IS NULL AND g.order_type = 'I' AND h.starttime BETWEEN 72 AND 112 THEN f.infusion_rate_adjustment END), 0) AS ratio FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.hadm_id = d.hadm_id JOIN procedureevents e ON a.hadm_id = e.subject_id JOIN emar_detail f ON e.order_provider_id = f.poe_id JOIN poe g ON f.poe_id = g.poe_id JOIN inputevents h ON h.linkorderid = g.order_type;